-- Correction des modèles du lot P2 de la Primaire publique (202610231302) : leurs variables doivent appartenir à la liste blanche du
-- socle Messaging (TemplateRenderer::ALLOWED). La migration d'origine n'est pas modifiée : les textes sont remplacés ici.
-- pub.eva_na.parent : discipline -> :subject, unité -> :label ; pub.pas.parent : décision -> :details, fin du recours -> :due_on.
UPDATE message_templates SET body = ':child_name n''a pas encore acquis la discipline :subject (:label). L''enseignant vous propose une rencontre à :establishment_name.', variables = '["child_name","subject","label","establishment_name"]', updated_at = '2026-10-28T09:00:00+01:00' WHERE tenant_id = 'platform' AND template_key = 'pub.eva_na.parent' AND locale = 'fr';
UPDATE message_templates SET body = ':child_name has not yet achieved :subject (:label). The teacher offers to meet you at :establishment_name.', variables = '["child_name","subject","label","establishment_name"]', updated_at = '2026-10-28T09:00:00+01:00' WHERE tenant_id = 'platform' AND template_key = 'pub.eva_na.parent' AND locale = 'en';
UPDATE message_templates SET body = 'Conseil des maîtres :school_year : décision pour :child_name : :details. Recours possible auprès du directeur jusqu''au :due_on.', variables = '["school_year","child_name","details","due_on"]', updated_at = '2026-10-28T09:00:00+01:00' WHERE tenant_id = 'platform' AND template_key = 'pub.pas.parent' AND locale = 'fr';
UPDATE message_templates SET body = 'Staff council :school_year: decision for :child_name: :details. You may appeal to the head teacher until :due_on.', variables = '["school_year","child_name","details","due_on"]', updated_at = '2026-10-28T09:00:00+01:00' WHERE tenant_id = 'platform' AND template_key = 'pub.pas.parent' AND locale = 'en';
